var t=[{title:`Semaine un : apprendre la routine`,text:`Choisissez deux courtes séances sur tout le corps, et faites des marches faciles les autres jours si vous en avez envie. Pratiquez les schémas de base du squat, de la charnière, de la poussée, de la traction et du gainage avec des mouvements adaptés à votre équipement et à votre corps. Une première séance peut comprendre une ou deux séries de plusieurs exercices.`},{title:`Semaines deux à quatre : répéter et observer`,text:`Gardez les mêmes exercices, puis ajoutez lentement des répétitions, un peu de charge ou une série supplémentaire si vous récupérez bien. De petites augmentations que vous pouvez tenir aident à gagner en confiance. Ne voyez pas chaque nouvelle sensation ou chaque courbature comme une raison de changer tout le programme.`},{title:`Exemple`,text:`Le lundi et le jeudi, faites des squats sur chaise contrôlés, des rowings avec appui, des pompes contre un mur et un court gainage. Ajoutez une marche confortable un autre jour. Si un mouvement est trop difficile, choisissez une version plus facile. S’il est très facile, rendez-le plus difficile graduellement tout en gardant le contrôle.`},{title:`À quoi s’attendre au début`,text:`Les premiers gains de force viennent souvent d’une meilleure technique et d’une meilleure coordination entre vos nerfs et vos muscles, et les changements physiques se voient davantage avec le temps. Une séance manquée n’efface pas vos progrès. Reprenez simplement à la prochaine séance prévue.`},{title:`Avec TrainUp`,text:`Indiquez honnêtement votre niveau de forme dans Profil, ainsi que l’équipement dont vous disposez et la durée de vos séances. Après chaque séance, évaluez votre effort (RPE). Votre programme ne change que lorsque vous le régénérez, et jamais sur la base de moins de 3 séances. Si vos 4 dernières séances ont été faciles (RPE 5 ou moins) et complètes, le programme suivant monte d’un cran.`}];var n=[{label:`ACSM 2026 : conseils pratiques`,url:`https://www.acsm.org/wp-content/uploads/2026/03/Resistance-Training-Position-Stand-infographic.pdf`},{label:`NHS : la marche pour la santé`,url:`https://www.nhs.uk/live-well/exercise/walking-for-health/`}];var a={sections:t,sources:n};export{a as default,t as sections,n as sources};